package org.bukkit.util; public class BoundingBox { private final double minX,minY,minZ,maxX,maxY,maxZ; public BoundingBox(double x,double y,double z,double X,double Y,double Z){minX=x;minY=y;minZ=z;maxX=X;maxY=Y;maxZ=Z;} public double getMinX(){return minX;} public double getMinY(){return minY;} public double getMinZ(){return minZ;} public double getMaxX(){return maxX;} public double getMaxY(){return maxY;} public double getMaxZ(){return maxZ;} }
